// CSD_RATIONALE_BEGIN
// Root cause analysis (attempt 43, 52.0%): IsCompletePrefix fires after only 3-4
// constrained tokens (e.g., "SELECT id FROM highschooler") because "SELECT col FROM
// table" is a grammatically complete SQL statement. We then immediately close the
// span, never generating WHERE/JOIN/GROUP BY/ORDER BY/HAVING/INTERSECT clauses.
// The failing outputs confirm this: "SELECT id FROM high>>", "SELECT DISTINCT
// s1.country FROM singer>>", "SELECT a.address_id,...FROM addresses>>".
//
// The key fix: Remove IsCompletePrefix early-close from the constrained generation
// loop. Let the model continue generating via GroupBoostedConstrainedStep until it
// naturally selects EOS (meaning it is satisfied with the SQL). Only close when EOS
// is chosen AND IsCompletePrefix holds. Use CloseSpanWithinBudget as a fallback for
// cases where EOS is never chosen within budget.
//
// Why attempt 40 failed (46.7%): it added a sqlTokenCap=150 after which
// CloseSpanWithinBudget(80) was forced, terminating spans mid-clause. This attempt
// removes that cap and lets the model consume its full step budget.
//
// Additional improvements:
// 1. Revised guidance to strongly emphasize complete SQL with all clauses.
// 2. Keep GroupBoostedConstrainedStep(6.0) for schema-token preference.
// 3. Keep preamble ≤ 5 steps; force OpenConstrainedSpan if model doesn't open span.
// 4. CloseSpanWithinBudget fallback uses full remaining budget (no 80-step cap).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble): Loop guard requires !insideConstrainedOut. When
//   RenderedEndsWith(generated, "<<") fires, we set currentConstrainedOut := [].
//   parser.IsValidPrefix([]) holds by method precondition. On EOS break,
//   insideConstrainedOut stays false, making the implication vacuously true.
//
// Phase 2 (OpenConstrainedSpan): Only runs when !insideConstrainedOut. Helper sets
//   currentConstrainedOut := []; IsValidPrefix([]) holds by precondition.
//
// Phase 3 (main SQL loop): GroupBoostedConstrainedStep hard-masks to parser-valid
//   tokens plus EOS. If next == eosToken, we either close (CloseConstrainedSpan sets
//   insideConstrainedOut := false, making the implication vacuously true, and clears
//   currentConstrainedOut := []) or break without changing span state (invariant
//   carries over from previous iteration). If next != eosToken, AppendConstrainedToken
//   extends currentConstrainedOut by one parser-valid token, preserving IsValidPrefix
//   by the parser extension contract.
//
// Phase 4 (CloseSpanWithinBudget): Postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut). Both the closed path (insideOut
//   false, implication vacuous) and the still-open path (valid prefix) preserve the
//   invariant.
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token
//   (0 for EOS, 1 for non-EOS). Invariant is preserved each iteration.
//
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<"
//   token. Both generated length and steps grow by 1; invariant preserved.
//
// Phase 3: Each GroupBoostedConstrainedStep increments steps by 1. On EOS: we break
//   (generated unchanged since EOS is not appended) or close (CloseConstrainedSpan
//   appends at most 1 ">>" token and increments steps by 1; net ≤1 token per 1 step).
//   On non-EOS: AppendConstrainedToken appends exactly 1 token; net 1:1 with steps.
//   Each branch satisfies the invariant.
//
// Phase 4: CloseSpanWithinBudget postcondition gives |generatedOut| <= |generated|
//   + closeBudget. We set steps := steps + closeBudget (the full allocated budget),
//   so |generated| <= |generatedPrefix| + steps_before_phase4 + closeBudget =
//   |generatedPrefix| + steps_after_phase4. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a COMPLETE SQL query that fully answers the question. Use ONLY exact table and column names from the schema. You MUST include WHERE for filtering, JOIN for multiple tables, GROUP BY for aggregation, ORDER BY for sorting, HAVING for group conditions, INTERSECT/UNION for set operations - whenever the question requires them. Never stop after only 'SELECT col FROM table' if the question asks for filtering, ordering, grouping, or combining results. Output format: SQL: <<complete SQL query>>");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble to allow "SQL: " prefix emission
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if model hasn't opened it
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL without IsCompletePrefix early-close.
// Let model continue past "SELECT col FROM table" until it naturally selects EOS,
// allowing WHERE/JOIN/GROUP BY/ORDER BY/HAVING/INTERSECT to be generated.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.GroupBoostedConstrainedStep(
    lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
  );
  steps := steps + 1;
  if next == eosToken {
    // Only close when the model wants to stop AND the SQL is complete
    if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    }
    break;
  } else {
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

// Phase 4: Fallback close if span is still open (EOS never chosen or SQL incomplete)
if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

